{
  "@context": "https://schema.org",
  "@type": "WebApplication",
  "name": "Kalkulator Paparan Kebisingan K3 Online",
  "url": "https://wahanatotalita.com/tools/kalkulator-kebisingan/",
  "description": "Perhitungan dosis kebisingan kumulatif, Time Weighted Average (TWA), dan uji efektivitas APD pendengaran sesuai Permenaker No. 5 Tahun 2018.",
  "applicationCategory": "BusinessApplication",
  "operatingSystem": "All",
  "offers": { "@type": "Offer", "price": "0", "priceCurrency": "IDR" }
}

{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "Berapa Nilai Ambang Batas (NAB) kebisingan resmi di Indonesia?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Berdasarkan Permenaker No. 5 Tahun 2018 tentang K3 Lingkungan Kerja, Nilai Ambang Batas (NAB) kebisingan untuk waktu kerja 8 jam per hari atau 40 jam per minggu adalah 85 dBA dengan exchange rate 3 dB."
      }
    },
    {
      "@type": "Question",
      "name": "Bagaimana aturan penggandaan waktu pajanan kebisingan (3 dB exchange rate)?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Setiap kenaikan intensitas suara sebesar 3 dBA, batas waktu pemaparan yang diizinkan dipotong menjadi setengahnya. Sebagai contoh: 85 dBA diizinkan 8 jam, 88 dBA diizinkan 4 jam, 91 dBA diizinkan 2 jam, 94 dBA diizinkan 1 jam, dan pada 100 dBA hanya diizinkan maksimal 15 menit per hari tanpa APD."
      }
    },
    {
      "@type": "Question",
      "name": "Mengapa nilai NRR pada kemasan earplug / earmuff harus dikurangi (derated)?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Nilai NRR (Noise Reduction Rating) dari pabrikan diuji di laboratorium ideal. Standar OSHA dan NIOSH mensyaratkan derating karena di lapangan terdapat kebocoran pemasangan, rambut, kacamata, dan pergerakan rahang. Rumus OSHA mengoreksi NRR earplug dengan derating 50% setelah dikurangi 7 dB: Proteksi Riil = (NRR - 7) × 0.5."
      }
    }
  ]
}

inline_styles:
:root {
  --navy-dark: #071524;
  --navy: #0D233A;
  --navy-light: #183654;
  --orange: #E8611A;
  --orange-hover: #cf5213;
  --orange-light: #fff2ea;
  --slate-50: #F8FAFC;
  --slate-100: #F1F5F9;
  --slate-200: #E2E8F0;
  --slate-300: #CBD5E1;
  --slate-600: #475569;
  --slate-700: #334155;
  --slate-900: #0F172A;
  --radius-md: 12px;
  --radius-lg: 16px;
  --shadow-sm: 0 2px 8px rgba(13,35,58,0.06);
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
body {
  font-family: 'Source Sans 3', system-ui, -apple-system, sans-serif;
  background: var(--slate-50);
  color: var(--slate-900);
  line-height: 1.6;
}
.container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }

/* HERO */
.noise-hero {
  background: linear-gradient(135deg, #071524 0%, #0D233A 60%, #183654 100%);
  color: #fff;
  padding: 58px 0 44px;
  position: relative;
  overflow: hidden;
  border-bottom: 3px solid var(--orange);
}
.noise-hero::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: linear-gradient(rgba(255,255,255,0.03) 1px, transparent 1px),
                    linear-gradient(90deg, rgba(255,255,255,0.03) 1px, transparent 1px);
  background-size: 36px 36px;
  pointer-events: none;
}
.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: rgba(232, 97, 26, 0.18);
  border: 1px solid rgba(232, 97, 26, 0.4);
  padding: 6px 14px;
  border-radius: 999px;
  color: #FFA573;
  font-size: 0.8rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 14px;
}
.noise-hero h1 {
  font-family: 'Lexend', sans-serif;
  font-size: clamp(1.8rem, 3.6vw, 2.7rem);
  font-weight: 800;
  line-height: 1.2;
  margin-bottom: 12px;
}
.noise-hero h1 span { color: var(--orange); }
.noise-hero p {
  color: #CBD5E1;
  font-size: 1.05rem;
  max-width: 760px;
  margin-bottom: 20px;
}
.hero-tags { display: flex; flex-wrap: wrap; gap: 8px; }
.hero-tag {
  background: rgba(255,255,255,0.08);
  border: 1px solid rgba(255,255,255,0.12);
  padding: 4px 12px;
  border-radius: 6px;
  font-size: 0.82rem;
  color: #E2E8F0;
}

/* WORKSPACE LAYOUT */
.noise-wrapper { padding: 40px 0 60px; }
.noise-grid {
  display: grid;
  grid-template-columns: 1.15fr 0.85fr;
  gap: 32px;
  align-items: start;
}
@media (max-width: 992px) {
  .noise-grid { grid-template-columns: 1fr; }
}

.card-box {
  background: #fff;
  border: 1px solid var(--slate-200);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
  padding: 28px;
  margin-bottom: 28px;
}
.card-header-line {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 2px solid var(--slate-100);
  padding-bottom: 16px;
  margin-bottom: 22px;
}
.card-title {
  font-family: 'Lexend', sans-serif;
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--navy);
  display: flex;
  align-items: center;
  gap: 10px;
}

/* NOISE EXPOSURE TABLE */
.noise-table {
  width: 100%;
  border-collapse: collapse;
  margin-bottom: 18px;
  font-size: 0.9rem;
}
.noise-table th {
  background: var(--navy);
  color: #fff;
  padding: 10px 12px;
  text-align: left;
  font-size: 0.82rem;
}
.noise-table td {
  padding: 10px 12px;
  border-bottom: 1px solid var(--slate-200);
  vertical-align: middle;
}
.noise-input {
  width: 100%;
  padding: 8px 10px;
  border: 1.5px solid var(--slate-200);
  border-radius: 6px;
  font-size: 0.9rem;
}
.noise-input:focus { outline: none; border-color: var(--orange); }

.btn-add-source {
  background: var(--slate-100);
  border: 1.5px solid var(--slate-300);
  color: var(--navy);
  padding: 8px 16px;
  border-radius: 8px;
  font-size: 0.84rem;
  font-weight: 700;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.btn-add-source:hover { background: var(--slate-200); }

/* APD DERATING CALCULATOR */
.apd-box {
  background: var(--slate-50);
  border: 1px solid var(--slate-200);
  border-radius: var(--radius-md);
  padding: 18px;
  margin-top: 20px;
}
.apd-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
  margin-top: 12px;
}
@media (max-width: 600px) {
  .apd-grid { grid-template-columns: 1fr; }
}

/* RESULTS PANEL */
.result-stat-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
  margin-bottom: 22px;
}
.stat-card {
  background: var(--slate-50);
  border: 1px solid var(--slate-200);
  border-radius: var(--radius-md);
  padding: 16px;
  position: relative;
  overflow: hidden;
}
.stat-card.featured {
  background: linear-gradient(145deg, #0D233A 0%, #183654 100%);
  color: #fff;
  border-color: #0D233A;
}
.stat-card.featured .stat-meta { color: #FFA573; }
.stat-card.featured .stat-val { color: #fff; }
.stat-card.featured .stat-desc { color: #CBD5E1; }
.stat-card::after {
  content: "";
  position: absolute;
  top: 0; left: 0;
  width: 4px; height: 100%;
  background: var(--orange);
}
.stat-meta {
  font-size: 0.76rem;
  font-weight: 700;
  text-transform: uppercase;
  color: var(--slate-600);
  letter-spacing: 0.04em;
  margin-bottom: 4px;
}
.stat-val {
  font-family: 'Lexend', sans-serif;
  font-size: 1.8rem;
  font-weight: 800;
  color: var(--navy);
  line-height: 1.1;
  margin-bottom: 4px;
}
.stat-desc { font-size: 0.8rem; color: var(--slate-600); }

.status-box {
  padding: 14px 18px;
  border-radius: var(--radius-md);
  font-weight: 700;
  margin-bottom: 20px;
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 0.92rem;
}
.status-safe { background: #DCFCE7; color: #166534; border: 1px solid #BBF7D0; }
.status-warn { background: #FEF3C7; color: #92400E; border: 1px solid #FDE68A; }
.status-danger { background: #FEE2E2; color: #991B1B; border: 1px solid #FECACA; }

/* EDITORIAL ARTICLE */
.editorial-box {
  background: #fff;
  border: 1px solid var(--slate-200);
  border-radius: var(--radius-lg);
  padding: 36px;
  margin-bottom: 32px;
}
.editorial-title {
  font-family: 'Lexend', sans-serif;
  font-size: 1.45rem;
  font-weight: 800;
  color: var(--navy);
  margin-bottom: 16px;
  border-left: 4px solid var(--orange);
  padding-left: 14px;
}
.editorial-p {
  color: var(--slate-700);
  font-size: 0.96rem;
  line-height: 1.7;
  margin-bottom: 16px;
}
.ref-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.88rem;
  margin: 20px 0;
}
.ref-table th {
  background: var(--navy);
  color: #fff;
  padding: 10px 14px;
  text-align: left;
}
.ref-table td {
  padding: 9px 14px;
  border-bottom: 1px solid var(--slate-200);
  color: var(--slate-700);
}
.ref-table tr:nth-child(even) td { background: var(--slate-50); }

/* FAQ */
.faq-item {
  border: 1px solid var(--slate-200);
  border-radius: var(--radius-md);
  margin-bottom: 12px;
  overflow: hidden;
  background: #fff;
}
.faq-q {
  width: 100%;
  padding: 16px 20px;
  text-align: left;
  background: #fff;
  border: none;
  font-family: 'Lexend', sans-serif;
  font-size: 0.98rem;
  font-weight: 700;
  color: var(--navy);
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.faq-q:hover { background: var(--slate-50); }
.faq-a {
  padding: 0 20px 18px;
  color: var(--slate-700);
  font-size: 0.92rem;
  line-height: 1.65;
  display: none;
}
.faq-item.active .faq-a { display: block; }
.faq-item.active .faq-icon { transform: rotate(180deg); }
.faq-icon { transition: transform 0.2s; }

